return [
  {
    json: {
      signal: "new_hr_leader",
      weight: 5,
      query: '("appointed" OR "joins as" OR "named") ("Head of HR" OR "Chief People Officer" OR "HR Director" OR "Head of People") (UAE OR Dubai OR "Abu Dhabi")',
      why: "New HR leaders set priorities and budgets in their first 90 days."
    }
  },
  {
    json: {
      signal: "expansion",
      weight: 4,
      query: '("opens" OR "launches" OR "inaugurates") ("regional headquarters" OR "new office" OR "Dubai hub" OR "new campus") (UAE OR Dubai OR "Abu Dhabi")',
      why: "A new or growing office means new hires, onboarding and culture-building needs."
    }
  },
  {
    json: {
      signal: "workplace_award",
      weight: 3,
      query: '("Great Place to Work" OR "Best Workplaces" OR "Top Employer") (UAE OR Dubai OR "Abu Dhabi" OR "Middle East")',
      why: "Employers proud of culture are buyers of programmes that reinforce it."
    }
  },
  {
    json: {
      signal: "wellbeing_push",
      weight: 3,
      query: '("employee wellbeing" OR "mental health" OR "wellness programme") (launches OR introduces OR partners) (UAE OR Dubai OR "Abu Dhabi") company',
      why: "A public wellbeing commitment signals budget and executive backing."
    }
  },
  {
    json: {
      signal: "hiring_surge",
      weight: 3,
      query: '("hiring" OR "to recruit" OR "create jobs") ("1,000" OR "500" OR "2,000" OR "thousands") (UAE OR Dubai OR "Abu Dhabi" OR "Saudi")',
      why: "Large hiring waves strain retention and onboarding, which wellbeing programmes support."
    }
  }
];

const items = $input.all();
const queryDefs = $('Define Signal Queries & Weights').all();
const days = 45;
const top = 12;

const NOISE = /\b(review|school|nursery|university|hospital|clinic|real estate agent|holiday|visa|tourism)\b/i;
const GEO = /\b(UAE|Dubai|Abu Dhabi|Sharjah|Emirates|Emirati|Gulf|GCC|Middle East|MENA)\b/i;
const GENERIC = /\b(people|culture|human resources|hr|great place|expo|forum|summit|awards?|ministry)\b/i;
const BAD = new Set([
  "Ghana", "Sharjah", "Apple", "The", "A", "An", "Dubai", "UAE", "Abu Dhabi",
  "How", "Why", "What", "New", "Top", "Best", "DIFC", "Dubai CommerCity",
  "CommerCity", "ADGM", "DMCC", "Gulf", "Middle East", "MENA", "GCC"
]);

const LEAD = /^([A-Z][\w&.\-' ]{1,40}?)\s+(?:opens|launches|inaugurates|unveils|announces|signs|expands|wins|named|ranked|recognised|certified|partners|appoints|to hire|to recruit|plans|introduces)\b/;
const AT = /\b(?:at|joins)\s+([A-Z][\w&.\-' ]{1,40}?)(?:\s+[-\u2013\u2014|]|$|\s+as\b|,)/g;

const SIGNAL_TEMPLATES = {
  "new_hr_leader": [
    "Congratulations on the new HR leadership appointment at {company}. The first 90 days are when wellbeing priorities get set. Would a 15-minute chat on what peer UAE employers do for movement programmes be useful?",
    "With new HR leadership taking the helm at {company}, shaping team culture is top of mind. We design human-led wellbeing sessions across the UAE. Could I share two practical ideas for your team?",
    "Stepping into an HR leadership role at {company} sets the tone for workforce wellbeing. We help UAE organisations launch high-participation activations. Worth a short intro call to compare notes?",
    "Welcome to the new People leadership team at {company}. Early tenure is an ideal window to introduce fresh health initiatives. Open to a brief 15-minute introductory conversation this week?"
  ],
  "expansion": [
    "Saw {company}'s expansion in the UAE. New offices usually need an early culture and wellbeing moment for the team settling in. We run onsite activations for exactly that stage. Open to a quick intro call?",
    "Congratulations on {company}'s new UAE office milestone. Welcoming new hires to a fresh workspace is the ideal moment to establish movement habits. Could I share two ideas that fit your team?",
    "Establishing a new UAE base for {company} creates an exciting culture-building window for incoming staff. We deliver human-led onsite team activations. Would a brief 15-minute conversation be timely?",
    "Following the launch of {company}'s new regional office, onboarding a growing workforce demands sustained team engagement. We organise turnkey corporate movement challenges. Worth a short chat to explore fit?"
  ],
  "workplace_award": [
    "Congratulations to {company} on the workplace recognition. Teams that earn it often want an engaging wellbeing programme to keep the momentum going. Could I share two ideas that fit your culture?",
    "Earning top employer recognition highlights {company}'s clear culture commitment. We help UAE organisations sustain employee energy with human-led activations. Would a brief 15-minute intro call be welcome?",
    "Celebrating {company}'s recent workplace culture award is a great milestone. Maintaining high engagement takes deliberate wellbeing moments. Open to a quick conversation on our onsite sessions?",
    "Recognised workplace cultures like {company}'s set high standards for employee experience. We build movement and wellness programmes that staff genuinely join. Worth a short intro chat?"
  ],
  "wellbeing_push": [
    "I noticed {company}'s recent wellbeing announcement. Many HR teams struggle to turn commitments into sessions staff actually attend. We design onsite and movement challenges that lift participation. Worth a short conversation?",
    "Committing publicly to employee wellbeing at {company} sets a great standard. Turning strategy into high participation is where we assist UAE employers. Could I share two ideas that fit your roadmap?",
    "Seeing {company}'s active wellbeing initiative is fantastic for the local workforce. We deliver human-led activations and challenges with zero operational friction. Would a brief 15-minute call be timely?",
    "With employee health now a priority at {company}, keeping staff actively engaged is the next step. We design tailored onsite workshops across the UAE. Open to a quick intro chat?"
  ],
  "hiring_surge": [
    "With {company} scaling the team so quickly, keeping new and existing staff engaged becomes the key HR challenge. We help with onsite activations and challenges that build belonging fast. Open to a brief intro?",
    "Rapid headcount growth at {company} puts team cohesion and onboarding to the test. We run turnkey movement challenges that connect colleagues quickly. Could I share two practical ideas?",
    "Scaling up hiring at {company} brings vital energy but also onboarding strain. We deliver human-led wellbeing sessions that help new joiners integrate comfortably. Would a brief 15-minute call be helpful?",
    "Welcoming large cohorts of new staff to {company} requires shared culture moments from day one. We design onsite corporate activations across the UAE. Worth a short conversation?"
  ]
};

function cleanDisplayName(name) {
  let s = name.replace(/\s+(?:Dubai office|Abu Dhabi office|regional headquarters|headquarters|HQ|Dubai hub|regional hub|office|offices|hub|hubs|Group|Middle East)\b/gi, "");
  s = s.replace(/^[ .,'\-]+|[ .,'\-]+$/g, "").trim();
  return s.length >= 2 ? s : name;
}

function normalizeKey(name) {
  let s = name.toLowerCase();
  s = s.replace(/\b(office|offices|hub|hubs|group|headquarters|hq|regional|campus|branch|branches|international|platform|platforms|middle east|uae|dubai|abu dhabi)\b/gi, "");
  s = s.replace(/^[ .,'\-]+|[ .,'\-]+$/g, "").trim();
  s = s.replace(/\s+/g, " ");
  return s;
}

function companyOf(title, hrRole = false) {
  title = title.replace(/\s+[-\u2013\u2014|]\s+[^-\u2013\u2014|]+$/, "").trim();
  let cands = [];
  if (hrRole) {
    const matches = [...title.matchAll(AT)];
    cands = matches.map(m => m[1]).reverse();
  } else {
    const leadMatch = title.match(LEAD);
    if (leadMatch) cands.push(leadMatch[1]);
    const matches = [...title.matchAll(AT)];
    for (const m of matches) {
      cands.push(m[1]);
    }
  }
  for (let c of cands) {
    c = c.replace(/^[ .,']+|[ .,']+$/g, "").trim();
    if (c && !BAD.has(c) && c.split(/\s+/).length <= 5 && !GENERIC.test(c)) {
      return c;
    }
  }
  return null;
}

function openerFor(company, signal) {
  const variants = SIGNAL_TEMPLATES[signal] || SIGNAL_TEMPLATES["expansion"];
  let hash = 0;
  for (let i = 0; i < company.length; i++) {
    hash = (hash + company.charCodeAt(i)) % variants.length;
  }
  return variants[hash].replace(/\{company\}/g, company);
}

function parseXmlItems(xmlText) {
  const list = [];
  if (!xmlText || typeof xmlText !== 'string') return list;
  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xmlText)) !== null) {
    const block = match[1];
    const tm = block.match(/<title>([\s\S]*?)<\/title>/i);
    const lm = block.match(/<link>([\s\S]*?)<\/link>/i);
    const pm = block.match(/<pubDate>([\s\S]*?)<\/pubDate>/i);
    let title = tm ? tm[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, "$1").trim() : "";
    let link = lm ? lm[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, "$1").trim() : "";
    let pubDate = pm ? pm[1].trim() : "";
    title = title.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
    if (title) list.push({ title, link, pubDate });
  }
  return list;
}

const found = {};
const now = new Date();
const badLower = new Set([...BAD].map(b => b.toLowerCase()));

for (let idx = 0; idx < items.length; idx++) {
  const it = items[idx];
  const qDef = (queryDefs[idx] && queryDefs[idx].json) ? queryDefs[idx].json : {};
  const signalName = qDef.signal || it.json.signal;
  const weight = qDef.weight || 3;
  const why = qDef.why || "";
  const xmlData = it.json.data || it.data || "";

  const parsedItems = parseXmlItems(xmlData);

  for (const item of parsedItems) {
    const title = item.title;
    if (NOISE.test(title) || !GEO.test(title)) continue;
    const company = companyOf(title, signalName === "new_hr_leader");
    if (!company) continue;

    const disp = cleanDisplayName(company);
    const norm = normalizeKey(disp);
    if (!norm || badLower.has(norm) || BAD.has(company) || BAD.has(disp)) continue;

    const pubTime = item.pubDate ? new Date(item.pubDate).getTime() : now.getTime();
    const age = Math.max(Math.floor((now.getTime() - pubTime) / (1000 * 60 * 60 * 24)), 0);
    const score = weight * (1.0 - Math.min(age, days) / (days * 1.5));

    if (!found[norm]) {
      found[norm] = {
        company: disp,
        score: 0.0,
        signals: new Set(),
        evidence: []
      };
    } else {
      if (disp.length < found[norm].company.length) {
        found[norm].company = disp;
      }
    }
    found[norm].score += score;
    found[norm].signals.add(signalName);
    found[norm].evidence.push({
      age,
      title,
      link: item.link,
      signal: signalName,
      why
    });
  }
}

const sortedLeads = Object.values(found).sort((a, b) => {
  const scoreA = a.score + 1.5 * (a.signals.size - 1);
  const scoreB = b.score + 1.5 * (b.signals.size - 1);
  return scoreB - scoreA;
}).slice(0, top);

const output = [];
for (const l of sortedLeads) {
  l.evidence.sort((a, b) => a.age - b.age);
  const best = l.evidence[0];
  const primarySignal = best.signal;
  const signalsList = Array.from(l.signals).sort();
  const templateOpener = openerFor(l.company, primarySignal);

  output.push({
    json: {
      company: l.company,
      signal: primarySignal,
      signals: signalsList.join(', '),
      score: parseFloat(l.score.toFixed(2)),
      age_days: best.age,
      headline: best.title,
      evidence_link: best.link,
      why: best.why,
      target_roles: "Head of HR / People & Culture / Employee Experience",
      template_opener: templateOpener,
      opener: templateOpener,
      opener_source: "template",
      status: "New",
      found_at: now.toISOString()
    }
  });
}

return output;

