parameters.jsCode:
const leads = $('Clean, Extract & Score Leads').all();
const items = $input.all();
const results = [];

for (let i = 0; i < leads.length; i++) {
  const lead = leads[i].json;
  const aiItem = (items[i] && items[i].json) ? items[i].json : {};

  let opener = lead.template_opener || lead.opener;
  let source = "template";

  // Check if AI call succeeded and extract all text parts
  const candidates = aiItem.candidates || (aiItem.data && aiItem.data.candidates);
  if (candidates && candidates[0] && candidates[0].content && candidates[0].content.parts) {
    const rawText = candidates[0].content.parts
      .map(p => p.text || '')
      .join('')
      .trim()
      .replace(/^[\"\']+|[\"\']+$/g, '');

    // Sanitize any em/en-dashes and normalize spaces
    const cleanText = rawText.replace(/[\u2014\u2013]/g, ' - ').replace(/\s+/g, ' ').trim();
    const words = cleanText ? cleanText.split(/\s+/).length : 0;

    // Accept valid AI opener strictly under 40 words
    if (words >= 15 && words < 40) {
      opener = cleanText;
      source = "ai";
    }
  }

  results.push({
    json: {
      company: lead.company,
      signal: lead.signal,
      signals: lead.signals,
      score: lead.score,
      age_days: lead.age_days,
      headline: lead.headline,
      evidence_link: lead.evidence_link,
      target_roles: lead.target_roles,
      why: lead.why,
      opener: opener,
      opener_source: source,
      status: "New",
      found_at: lead.found_at || new Date().toISOString()
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  let body = {};
  try {
    const hookNode = $('Webhook (POST /wellbayt-reply)').first();
    body = (hookNode && hookNode.json && hookNode.json.body) ? hookNode.json.body : (hookNode ? hookNode.json : {});
  } catch (e) {
    body = item.json && item.json.body ? item.json.body : item.json || {};
  }

  const company = body.company || "Target Company";
  const replyText = (body.reply_text || "").trim();
  const lower = replyText.toLowerCase();

  let classification = "question";
  let crm_status = "Active Conversation - Information Requested";
  let next_step = "Provide concise answer and propose 10-minute briefing call.";
  let needs_human_check = false;
  let draft_reply = `Thank you for reaching out. Wellbayt provides human-led onsite and virtual wellbeing sessions, corporate activations, an employer dashboard, and our employee app across the UAE. Would a brief 10-minute introductory call be helpful to explore what fits your team?`;
  let source = "rule_based";

  // Check if AI classification succeeded
  const candidates = item.json && (item.json.candidates || (item.json.data && item.json.data.candidates));
  if (candidates && candidates[0] && candidates[0].content && candidates[0].content.parts) {
    try {
      const raw = candidates[0].content.parts
        .map(p => p.text || '')
        .join('')
        .trim()
        .replace(/^```json\s*|^```\s*|```$/g, '');
      const parsed = JSON.parse(raw);
      if (parsed.classification && ["interested", "not_now", "not_interested", "out_of_office", "question"].includes(parsed.classification)) {
        classification = parsed.classification;
        crm_status = parsed.crm_status || crm_status;
        next_step = parsed.next_step || next_step;
        needs_human_check = typeof parsed.needs_human_check === 'boolean' ? parsed.needs_human_check : false;
        if (parsed.draft_reply && parsed.draft_reply.length > 10) {
          draft_reply = parsed.draft_reply.replace(/[\u2014\u2013]/g, ' - ').replace(/\s+/g, ' ').trim();
        }
        source = "ai";
      }
    } catch (err) {}
  }

  // Rule-based fallback if AI failed
  if (source === "rule_based") {
    if (/\b(price|pricing|cost|rate|rates|budget|quote|counselling|therapy|gym|scope)\b/i.test(lower)) {
      needs_human_check = true;
    }

    if (/\b(interested|call|talk|sounds good|available|let's connect|schedule|yes|meet)\b/i.test(lower)) {
      classification = "interested";
      crm_status = "Qualified - Meeting Requested";
      next_step = "Share meeting link and agree on preferred 15-minute slot.";
      draft_reply = `Thank you for the reply. I would be glad to share two practical ideas for onsite movement and wellbeing activations that fit ${company}. Would Tuesday or Thursday afternoon suit you for a brief 15-minute intro call?`;
    } else if (/\b(not now|later|next quarter|busy|next year|revisit|reach out in|q[1-4])\b/i.test(lower)) {
      classification = "not_now";
      crm_status = "Nurture - Follow up next quarter";
      next_step = "Set CRM reminder for a 60-day check-in.";
      draft_reply = `Completely understand. Thank you for the note. I will make a note to follow up in a couple of months when your team's planning cycle reopens. Wishing you all the best in the meantime.`;
    } else if (/\b(not interested|unsubscribe|remove|stop|no thanks|never)\b/i.test(lower)) {
      classification = "not_interested";
      crm_status = "Disqualified - Closed";
      next_step = "Mark contact as Do Not Contact in CRM.";
      draft_reply = `Thank you for letting me know. I have updated our records so you will not hear from us again. All the best to you and the team at ${company}.`;
    } else if (/\b(out of the office|away from my desk|annual leave|maternity|paternity|auto-reply)\b/i.test(lower)) {
      classification = "out_of_office";
      crm_status = "Out of Office - Pending Return";
      next_step = "Wait for prospect return date before following up.";
      draft_reply = `[Auto-reply recorded: Follow-up paused until contact returns to office]`;
    } else {
      if (needs_human_check) {
        draft_reply = `Thank you for reaching out. Wellbayt provides human-led onsite and virtual activations, an employer dashboard, and our wellbeing app. Regarding the specific scope and pricing details, I will confirm with our team and come back to you shortly.`;
      }
    }
  }

  results.push({
    json: {
      company: company,
      reply_text: replyText,
      classification: classification,
      crm_status: crm_status,
      next_step: next_step,
      needs_human_check: needs_human_check,
      draft_reply: draft_reply,
      classifier_source: source,
      reviewed_by_human: false,
      processed_at: new Date().toISOString()
    }
  });
}

return results;

